import { injectable } from 'tsyringe-neo'
import { Handler, Id, z } from '@bk-dash/core-typescript'
import type { Transaction } from '@bk-dash/core-typescript'
import { LeadCapturedEvent } from '../events'
import type { DomainErrors } from '../errors'

export const CaptureLeadInputSchema = z.object({
	email: z.string().email({ error: 'INVALID_EMAIL' as DomainErrors }),
	name: z.string().optional(),
	phoneNumber: z.string().optional(),
})

export const CaptureLeadOutputSchema = z.void()

@injectable()
export class CaptureLead extends Handler<typeof CaptureLeadInputSchema, typeof CaptureLeadOutputSchema> {
	readonly name = 'capture_lead' as const
	readonly inputSchema = CaptureLeadInputSchema
	readonly outputSchema = CaptureLeadOutputSchema

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			// Pre-signup leads have no auth.users row yet; use a deterministic
			// UUID derived from the email so the entity id is stable across
			// retries (events.entity_id is uuid in the schema).
			const leadId = Id.fromSeed('identity', 'lead', input.email).value
			const event = new LeadCapturedEvent({
				entityId: leadId,
				ownerId: leadId,
				payload: {
					email: input.email,
					capturedAt: new Date().toISOString(),
					name: input.name,
					phoneNumber: input.phoneNumber,
				},
			})
			await this.domainEventRepository.save(event, tx)
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { CaptureLead, CaptureLeadInputSchema } from '../usecases/CaptureLead'

export const CaptureLeadControllerInputSchema = CaptureLeadInputSchema.example([
	{ email: 'lead@example.com', name: 'Lead Name', phoneNumber: '+5511999999999' },
])

export const CaptureLeadControllerOutputSchema = z.void()

@injectable()
export class CaptureLeadController extends Controller<typeof CaptureLeadControllerInputSchema, typeof CaptureLeadControllerOutputSchema> {
	readonly path = '/identity/leads'
	readonly method = 'post' as const
	readonly description = 'Capture a marketing lead (pre-signup email + optional name/phone)'
	readonly inputSchema = CaptureLeadControllerInputSchema
	readonly outputSchema = CaptureLeadControllerOutputSchema

	constructor(private captureLead: CaptureLead) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.captureLead.execute({
			email: request.email,
			name: request.name,
			phoneNumber: request.phoneNumber,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

import { BaseDomainEvent, z } from '@bk-dash/core-typescript'

export const LeadCapturedEventSchema = z.domainEvent({
	email: z.string(),
	capturedAt: z.iso.datetime({ offset: true }),
	name: z.string().optional(),
	phoneNumber: z.string().optional(),
})

export class LeadCapturedEvent extends BaseDomainEvent<typeof LeadCapturedEventSchema> {
	static override readonly name = 'identity.lead.captured' as const
	static readonly schema = LeadCapturedEventSchema
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed } from '@test/support'
import { DomainEventRepository, Id } from '@bk-dash/core-typescript'
import { CaptureLead } from './CaptureLead'
import { LeadCapturedEvent } from '../events'

describe('CaptureLead use case (C01)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let captureLead: CaptureLead

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer })
		captureLead = testBed.resolve(CaptureLead)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readLeadCapturedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(LeadCapturedEvent)
	}

	it('persists a LeadCapturedEvent with the email + capturedAt + optional fields', async () => {
		await captureLead.execute({
			email: 'lead@b.com',
			name: 'Lead',
			phoneNumber: '+5511999999999',
		})

		const evs = await readLeadCapturedEvents()

		const expectedEntityId = Id.fromSeed('identity', 'lead', 'lead@b.com').value
		expect(evs).toHaveLength(1)
		expect(evs[0]!.entityId).toBe(expectedEntityId)
		expect(evs[0]!.payload.email).toBe('lead@b.com')
		expect(evs[0]!.payload.name).toBe('Lead')
		expect(evs[0]!.payload.phoneNumber).toBe('+5511999999999')
		expect(typeof evs[0]!.payload.capturedAt).toBe('string')
	})

	it('persists a minimal lead (email only — name and phoneNumber omitted)', async () => {
		await captureLead.execute({ email: 'min@b.com' })

		const evs = await readLeadCapturedEvents()

		expect(evs).toHaveLength(1)
		expect(evs[0]!.payload.email).toBe('min@b.com')
		expect(evs[0]!.payload.name).toBeUndefined()
		expect(evs[0]!.payload.phoneNumber).toBeUndefined()
	})

	it('rejects invalid email with INVALID_EMAIL', async () => {
		await expect(captureLead.execute({ email: 'not-an-email' })).rejects.toThrow(/INVALID_EMAIL/)
	})

	it('emits a fresh event on each call (no idempotency at this phase)', async () => {
		await captureLead.execute({ email: 'dup@b.com' })
		await captureLead.execute({ email: 'dup@b.com' })

		const evs = await readLeadCapturedEvents()

		expect(evs).toHaveLength(2)
	})
})

