import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { CaptureLead, CaptureLeadInputSchema } from '../usecases/CaptureLead'

export const CaptureLeadControllerInputSchema = CaptureLeadInputSchema.example([
	{ email: 'lead@example.com', name: 'Lead Name', phoneNumber: '+5511999999999' },
])

export const CaptureLeadControllerOutputSchema = z.void()

@injectable()
export class CaptureLeadController extends Controller<typeof CaptureLeadControllerInputSchema, typeof CaptureLeadControllerOutputSchema> {
	readonly path = '/ui/leads'
	readonly method = 'post' as const
	readonly description = 'Capture a marketing lead (pre-signup email + optional name/phone)'
	readonly inputSchema = CaptureLeadControllerInputSchema
	readonly outputSchema = CaptureLeadControllerOutputSchema

	constructor(private captureLead: CaptureLead) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		await this.captureLead.execute({
			email: request.email,
			name: request.name,
			phoneNumber: request.phoneNumber,
		})
		return { status: HttpStatusCode.NO_CONTENT, data: undefined }
	}
}

