import { describe, expect, it } from 'bun:test'
import { FcmPlatform, NotificationCurrencyMode } from '@bk-dash/contracts-typescript/wire/enums'
import {
	LeadCapturedEvent,
	UserRegisteredEvent,
	UserSignedInEvent,
	UserSignedOutEvent,
	ProfileUpdatedEvent,
	PasswordChangedEvent,
	PasswordResetRequestedEvent,
	PasswordResetEvent,
	FcmTokenRegisteredEvent,
	FcmTokenUnregisteredEvent,
	UserPreferencesCreatedEvent,
	UserPreferencesUpdatedEvent,
} from './index'

describe('Identity domain events', () => {
	it('event names follow identity.<entity>.<verb> convention', () => {
		expect(LeadCapturedEvent.name).toBe('identity.lead.captured')
		expect(UserRegisteredEvent.name).toBe('identity.user.registered')
		expect(UserSignedInEvent.name).toBe('identity.user.signed_in')
		expect(UserSignedOutEvent.name).toBe('identity.user.signed_out')
		expect(ProfileUpdatedEvent.name).toBe('identity.user.profile_updated')
		expect(PasswordChangedEvent.name).toBe('identity.user.password_changed')
		expect(PasswordResetRequestedEvent.name).toBe('identity.user.password_reset_requested')
		expect(PasswordResetEvent.name).toBe('identity.user.password_reset')
		expect(FcmTokenRegisteredEvent.name).toBe('identity.fcm_token.registered')
		expect(FcmTokenUnregisteredEvent.name).toBe('identity.fcm_token.unregistered')
		expect(UserPreferencesCreatedEvent.name).toBe('identity.user_preferences.created')
		expect(UserPreferencesUpdatedEvent.name).toBe('identity.user_preferences.updated')
	})

	it('LeadCapturedEvent payload validates a minimal lead', () => {
		const e = new LeadCapturedEvent({
			entityId: 'a@b.com',
			ownerId: 'a@b.com',
			payload: { email: 'a@b.com', capturedAt: new Date().toISOString() },
		})
		expect(e.payload.email).toBe('a@b.com')
		expect(e.payload.name).toBeUndefined()
	})

	it('UserRegisteredEvent payload requires userId + email + carries optional leadEmail', () => {
		const e = new UserRegisteredEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', email: 'a@b.com', leadEmail: 'a@b.com' },
		})
		expect(e.payload.userId).toBe('u1')
		expect(e.payload.leadEmail).toBe('a@b.com')
	})

	it('UserSignedInEvent + UserSignedOutEvent carry their respective timestamps', () => {
		const inE = new UserSignedInEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', signedInAt: new Date().toISOString() },
		})
		const outE = new UserSignedOutEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', signedOutAt: new Date().toISOString() },
		})
		expect(inE.payload.signedInAt).toBeDefined()
		expect(outE.payload.signedOutAt).toBeDefined()
	})

	it('ProfileUpdatedEvent payload carries userProfile key typed by UserProfileSchema', () => {
		const e = new ProfileUpdatedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: {
				userProfile: { userId: 'u1' } as never,
			},
		})
		expect(e.payload.userProfile).toBeDefined()
		expect((e.payload.userProfile as unknown as { userId: string }).userId).toBe('u1')
	})

	it('Password* events all carry userId + a verb-specific timestamp', () => {
		const now = new Date().toISOString()
		const changed = new PasswordChangedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', changedAt: now },
		})
		const requested = new PasswordResetRequestedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', requestedAt: now },
		})
		const reset = new PasswordResetEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', resetAt: now },
		})
		expect(changed.payload.changedAt).toBe(now)
		expect(requested.payload.requestedAt).toBe(now)
		expect(reset.payload.resetAt).toBe(now)
	})

	it('FcmTokenRegisteredEvent payload requires a known FcmPlatform', () => {
		const e = new FcmTokenRegisteredEvent({
			entityId: 'tok-1',
			ownerId: 'u1',
			payload: { userId: 'u1', tokenId: 'tok-1', platform: FcmPlatform.IOS },
		})
		expect(e.payload.platform).toBe(FcmPlatform.IOS)
	})

	it('FcmTokenUnregisteredEvent payload carries userId + tokenId', () => {
		const e = new FcmTokenUnregisteredEvent({
			entityId: 'tok-1',
			ownerId: 'u1',
			payload: { userId: 'u1', tokenId: 'tok-1' },
		})
		expect(e.payload.tokenId).toBe('tok-1')
	})

	it('UserPreferencesCreatedEvent payload carries only userId', () => {
		const e = new UserPreferencesCreatedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1' },
		})
		expect(e.payload.userId).toBe('u1')
	})

	it('UserPreferencesUpdatedEvent payload carries userPreferences key typed by UserPreferencesSchema', () => {
		const e = new UserPreferencesUpdatedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: {
				userPreferences: {
					userId: 'u1',
					notificationCurrencyMode: NotificationCurrencyMode.CUSTOM_CURRENCY,
					customCurrency: 'BRL',
					dailyNotificationsEnabled: false,
					orderPushPerStore: {},
				} as never,
			},
		})
		expect(e.payload.userPreferences).toBeDefined()
		expect((e.payload.userPreferences as { notificationCurrencyMode: string }).notificationCurrencyMode).toBe(
			NotificationCurrencyMode.CUSTOM_CURRENCY,
		)
	})
})

