		const changed = new PasswordChangedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', changedAt: now },
		})
		const requested = new PasswordResetRequestedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', requestedAt: now },
		})
		const reset = new PasswordResetEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1', resetAt: now },
		})
		expect(changed.payload.changedAt).toBe(now)
		expect(requested.payload.requestedAt).toBe(now)
		expect(reset.payload.resetAt).toBe(now)
	})

	it('FcmTokenRegisteredEvent payload requires a known FcmPlatform', () => {
		const e = new FcmTokenRegisteredEvent({
			entityId: 'tok-1',
			ownerId: 'u1',
			payload: { userId: 'u1', tokenId: 'tok-1', platform: FcmPlatform.IOS },
		})
		expect(e.payload.platform).toBe(FcmPlatform.IOS)
	})

	it('FcmTokenUnregisteredEvent payload carries userId + tokenId', () => {
		const e = new FcmTokenUnregisteredEvent({
			entityId: 'tok-1',
			ownerId: 'u1',
			payload: { userId: 'u1', tokenId: 'tok-1' },
		})
		expect(e.payload.tokenId).toBe('tok-1')
	})

	it('UserPreferencesCreatedEvent payload carries only userId', () => {
		const e = new UserPreferencesCreatedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: { userId: 'u1' },
		})
		expect(e.payload.userId).toBe('u1')
	})

	it('UserPreferencesUpdatedEvent payload carries userPreferences key typed by UserPreferencesSchema', () => {
		const e = new UserPreferencesUpdatedEvent({
			entityId: 'u1',
			ownerId: 'u1',
			payload: {
				userPreferences: {
					userId: 'u1',
					notificationCurrencyMode: NotificationCurrencyMode.CUSTOM_CURRENCY,
					customCurrency: 'BRL',
					dailyNotificationsEnabled: false,
					orderPushPerStore: {},
				} as never,
			},
		})
		expect(e.payload.userPreferences).toBeDefined()
		expect((e.payload.userPreferences as { notificationCurrencyMode: string }).notificationCurrencyMode).toBe(
			NotificationCurrencyMode.CUSTOM_CURRENCY,
		)
	})
})

