import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed } from '@test/support'
import { DomainEventRepository, Id } from '@bk-dash/core-typescript'
import { CaptureLead } from './CaptureLead'
import { LeadCapturedEvent } from '../events'

describe('CaptureLead use case (C01)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let captureLead: CaptureLead

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer })
		captureLead = testBed.resolve(CaptureLead)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readLeadCapturedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(LeadCapturedEvent)
	}

	it('persists a LeadCapturedEvent with the email + capturedAt + optional fields', async () => {
		await captureLead.execute({
			email: 'lead@b.com',
			name: 'Lead',
			phoneNumber: '+5511999999999',
		})

		const evs = await readLeadCapturedEvents()

		const expectedEntityId = Id.fromSeed('ui', 'lead', 'lead@b.com').value
		expect(evs).toHaveLength(1)
		expect(evs[0]!.entityId).toBe(expectedEntityId)
		expect(evs[0]!.payload.email).toBe('lead@b.com')
		expect(evs[0]!.payload.name).toBe('Lead')
		expect(evs[0]!.payload.phoneNumber).toBe('+5511999999999')
		expect(typeof evs[0]!.payload.capturedAt).toBe('string')
	})

	it('persists a minimal lead (email only — name and phoneNumber omitted)', async () => {
		await captureLead.execute({ email: 'min@b.com' })

		const evs = await readLeadCapturedEvents()

		expect(evs).toHaveLength(1)
		expect(evs[0]!.payload.email).toBe('min@b.com')
		expect(evs[0]!.payload.name).toBeUndefined()
		expect(evs[0]!.payload.phoneNumber).toBeUndefined()
	})

	it('rejects invalid email with INVALID_EMAIL', async () => {
		await expect(captureLead.execute({ email: 'not-an-email' })).rejects.toThrow(/INVALID_EMAIL/)
	})

	it('emits a fresh event on each call (no idempotency at this phase)', async () => {
		await captureLead.execute({ email: 'dup@b.com' })
		await captureLead.execute({ email: 'dup@b.com' })

		const evs = await readLeadCapturedEvents()

		expect(evs).toHaveLength(2)
	})
})

